head.script:
scwin.screenId = "jldfil25600";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name scwin.init_loadList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: entry_edge). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_load_list();
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_loadList();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil25600.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.grd_realsubmInfoList_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_realsubmInfoList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_realsubmInfoList');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_realsubmInfoList'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (columnId === "__rowAct") { if (typeof scwin.deleteRow === 'function') { await scwin.deleteRow(r["submitprnNm"], r["telNo"], r["submitprnEmail"]); } else { console.error('[sdd] 행 동작 미정의: scwin.deleteRow (열 삭제)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.deleteRow'); } return; } 
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_realsubmInfoList.oncellclick' });
    }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_deleteRow
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_deleteRow = async function () {
    const sbmOptions = {
        id: "tx_fn_deleteRow",
        method: "post",
        action: "/account/realsubmInfo.do",
        ref: "dma_deleteRowReq",
        target: "dlt_realsubmInfoList=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil25600.tx_fn_deleteRow" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_load_list
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_load_list = async function () {
    const sbmOptions = {
        id: "tx_load_list",
        method: "post",
        action: "/account/realsubmInfo.do?method=realsubmInfoList",
        ref: "dma_loadListReq",
        target: "dlt_realsubmInfoList=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil25600.tx_load_list" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @event
 * @name scwin.grd_realsubmInfoList_fillAct
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.grd_realsubmInfoList_fillAct = async function () {
    try {
        const dl = $c.util.getComponent('dlt_realsubmInfoList');
        if (!dl || !dl.getTotalRow) { return; }
        for (let i = 0; i < dl.getTotalRow(); i++) {
            const r = dl.getRowJSON(i);
            const v = '-';
            if (r) {  }
            dl.setCellData(i, "__rowAct", v);
        }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_realsubmInfoList.fillAct' });
    }
};

/**
 * @method
 * @name scwin.deleteRow
 * @author Inswave
 * @date 2026. 09. 29
 * @param ipt_submitprnNm ipt_telNo ipt_submitprnEmail
 * @returns
 * @hidden N
*/
scwin.deleteRow = async function (ipt_submitprnNm, ipt_telNo, ipt_submitprnEmail) {
    /* sdd-asis-lifecycle:begin fn_deleteRow — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const questionStr = "선택하신 제출인정보(" + ipt_submitprnNm + "/" + ipt_telNo + "/" + ipt_submitprnEmail + ")를 삭제하시겠습니까?";
    if (await $c.win.confirm(questionStr)) {
        const frm = (document.submitInformationForm || { elements: [] });
        frm.action = 'realsubmInfo.do';
        $c.util.getComponent('dma_deleteRowReq').set('method', "deleteRealsubmInfo");
        $c.util.getComponent('ipt_submitprnNm').setValue(ipt_submitprnNm);
        $c.util.getComponent('ipt_telNo').setValue(ipt_telNo);
        $c.util.getComponent('ipt_submitprnEmail').setValue(ipt_submitprnEmail);
        await scwin.tx_fn_deleteRow();
    }
    /* sdd-asis-lifecycle:end */
};
